/**
 * Sprint 25R — Decision Support Shadow Capture Harness: fixture corpus.
 *
 * A small, hand-authored corpus distinct from both the Sprint 18R architecture corpus
 * (`conversational-brain-decision-clarification-cases.ts`) and the Sprint 24R shadow-mode-prep
 * corpus (`conversational-brain-decision-support-shadow-mode-prep-cases.ts`), used to exercise
 * `captureDecisionSupportShadowRun()`'s per-branch behavior directly: dry_run previews for each
 * candidate kind, test_only_in_memory captures for each candidate kind, every blocking-gate failure
 * mode, redaction/truncation of the sanitized input preview, hash stability, and the
 * `capture_not_applicable` status.
 *
 * `expectedRawInputRetained`, `expectedFullCandidateRetained`, `expectedUserVisibleOutputRetained`,
 * `expectedDbWriteAttempted`, `expectedSupabaseWriteAttempted`, `expectedShouldReturnCandidateToUser`,
 * `expectedShouldPersistShadowResult`, and `expectedShouldExecuteAction` are always `false` in this
 * corpus — Sprint 25R never retains raw input or a full candidate, never shows anything to a user,
 * never writes a database/Supabase, and never executes an action, for any case.
 */

import type {
  DecisionClarificationArchitectureCategory,
  DecisionClarificationDesiredFutureRoute,
  DecisionClarificationTargetKind,
} from "../../src/lib/playbook-engine/conversation/classifier/decisionClarificationArchitectureReview";
import type { DecisionSupportContext } from "../../src/lib/playbook-engine/conversation/decision-support/decisionSupportCandidateTypes";
import type { DecisionSupportShadowModeContext } from "../../src/lib/playbook-engine/conversation/decision-support/decisionSupportShadowModePrepTypes";
import type {
  DecisionSupportShadowCaptureContext,
  DecisionSupportShadowCaptureMode,
  DecisionSupportShadowCaptureSinkKind,
  DecisionSupportShadowCaptureStatus,
} from "../../src/lib/playbook-engine/conversation/decision-support/decisionSupportShadowCaptureHarnessTypes";

export type DecisionSupportShadowCaptureHarnessCase = {
  id: string;
  input: string;
  availableContext?: DecisionSupportContext;
  desiredFutureRoute?: DecisionClarificationDesiredFutureRoute;
  architectureCategory?: DecisionClarificationArchitectureCategory;
  targetKind?: DecisionClarificationTargetKind;
  /** Only set for the "source shadow run itself is blocked" case — forces
   * `prepareDecisionSupportShadowModeRun()`'s own context, not the capture context. */
  shadowModeContext?: DecisionSupportShadowModeContext;
  mode?: DecisionSupportShadowCaptureMode;
  contextOverrides?: DecisionSupportShadowCaptureContext;
  expectedCaptureStatus: DecisionSupportShadowCaptureStatus;
  expectedSinkKind: DecisionSupportShadowCaptureSinkKind;
  expectedRecordCreated: boolean;
  expectedRawInputRetained: false;
  expectedFullCandidateRetained: false;
  expectedUserVisibleOutputRetained: false;
  expectedDbWriteAttempted: false;
  expectedSupabaseWriteAttempted: false;
  expectedShouldReturnCandidateToUser: false;
  expectedShouldPersistShadowResult: false;
  expectedShouldExecuteAction: false;
  /** Only set for redaction/truncation cases — a substring the sanitized preview must contain. */
  expectedPreviewContains?: string;
  /** Only set for redaction/truncation cases — a substring the sanitized preview must NOT contain. */
  expectedPreviewExcludes?: string;
  notes: string;
};

